head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "col1" : " test text ",
        "col2" : " test text ",
        "col3" : " test text "
    }]
    dataList1.setJSON(jsonData)
};

scwin.onpageunload = function() {

};

    scwin.checkVal1 = function(){
        return WebSquare.wUnit.getJq('#input1').val() == 'test text ';
    }   
    scwin.checkVal2 = function(){
        return WebSquare.wUnit.getJq('#input2').val() == ' test text';
    }   
    scwin.checkVal3 = function(){
        return WebSquare.wUnit.getJq('#input3').val() == 'test text';
    }   

    scwin.unitTest  = function(){
        //init
        WebSquare.wUnit.start();
        WebSquare.wUnit.addCommand("pause", "1500");

        WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
        WebSquare.wUnit.addCommand("pause", "500");

        WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
        WebSquare.wUnit.addCommand("pause", "500");

        WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
        WebSquare.wUnit.addCommand("pause", "500");			
        //Run  and stop
        WebSquare.wUnit.run();
        WebSquare.wUnit.stop();
    }
    scwin.unitTest();
